#include <bits/stdc++.h>
using namespace std;

class SegTree {
    int n;
    vector<long long> tree;
    void build(int node, int l, int r, const vector<long long>& a) {
        if (l == r) {
            tree[node] = a[l];
            return;
        }
        int mid = l + (r - l) / 2;
        build(node * 2, l, mid, a);
        build(node * 2 + 1, mid + 1, r, a);
        tree[node] = tree[node * 2] + tree[node * 2 + 1];
    }

void assign(int node, int l, int r, int position, long long value) {
    if (l == r) {
        tree[node] = value;
        return;
    }
    int mid = l + (r - l) / 2;
    if (position <= mid) {
        assign(node * 2, l, mid, position, value);
    } else {
        assign(node * 2 + 1, mid + 1, r, position, value);
    }
    tree[node] = tree[node * 2] + tree[node * 2 + 1];
}

    long long query_sum(int node, int l, int r, int ql, int qr) const {
        if (qr < l || r < ql) {
            return 0;
        }
        if (ql <= l && r <= qr) {
            return tree[node];
        }
        int mid = l + (r - l) / 2;
        return query_sum(node * 2, l, mid, ql, qr)
             + query_sum(node * 2 + 1, mid + 1, r, ql, qr);
    }
public:
    explicit SegTree(const vector<long long>& a)
        : n(static_cast<int>(a.size()) - 1), tree(4 * n) {
        build(1, 1, n, a);
    }
    void assign(int position, long long value) {
        assign(1, 1, n, position, value);
    }
    long long range_sum(int l, int r) const {
        return query_sum(1, 1, n, l, r);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<long long> a(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
    }
    SegTree tree(a);
    for (int query = 0; query < q; ++query) {
        int type;
        cin >> type;
        if (type == 1) {
            int position;
            long long value;
            cin >> position >> value;
            tree.assign(position, value);
        } else {
            int l, r;
            cin >> l >> r;
            cout << tree.range_sum(l, r) << '\n';
        }
    }
}

